<?php require '../config.php';if(!logged()){flash('Please login to use your cart.','error');redirect('../auth/login.php');}$action=$_POST['action']??'';$pid=(int)($_POST['product_id']??0);if($action==='add'){$s=$pdo->prepare('INSERT INTO cart_items(user_id,product_id,quantity) VALUES(?,?,1) ON DUPLICATE KEY UPDATE quantity=quantity+1');$s->execute([$_SESSION['user']['id'],$pid]);flash('Product added to cart.');}elseif($action==='update'){foreach($_POST['qty']??[] as $id=>$qty){$qty=max(1,min(20,(int)$qty));$s=$pdo->prepare('UPDATE cart_items SET quantity=? WHERE id=? AND user_id=?');$s->execute([$qty,(int)$id,$_SESSION['user']['id']]);}flash('Cart updated.');}elseif($action==='remove'){$s=$pdo->prepare('DELETE FROM cart_items WHERE id=? AND user_id=?');$s->execute([$pid,$_SESSION['user']['id']]);flash('Item removed.');}redirect('../cart.php'); ?>